<?php $e = fn ($v) => App\Core\View::e((string) $v); ?>
<div class="section-heading"><div><p class="eyebrow">Vai e Vem</p><h1><?= $e($item['sporting_name'] ?: $item['athlete_name']) ?></h1><p><?= $e($item['championship_name']) ?> · <?= $e($item['status']) ?></p></div><?php if (in_array($item['status'], ['draft', 'pending'], true)): ?><a class="button" href="<?= $e(App\Core\Config::url('/admin/vai-e-vem/' . $item['id'] . '/editar')) ?>">Editar</a><?php endif; ?></div>
<?php if (!empty($message)): ?><p class="flash-success"><?= $e($message) ?></p><?php endif; ?><dl class="detail-list"><dt>Movimento</dt><dd><?= $e($item['previous_team_name'] ?: '-') ?> → <?= $e($item['new_team_name'] ?: '-') ?></dd><dt>Tipo</dt><dd><?= $e($item['type']) ?></dd><dt>Data</dt><dd><?= $e($item['movement_date']) ?></dd><dt>Observacao publica</dt><dd><?= nl2br($e($item['public_observation'] ?: '-')) ?></dd><dt>Notas internas</dt><dd><?= nl2br($e($item['internal_notes'] ?: '-')) ?></dd><dt>Autor</dt><dd><?= $e($item['author_name']) ?></dd></dl>
<div class="inline-actions"><?php if ($item['status'] === 'pending'): ?><form method="post" action="<?= $e(App\Core\Config::url('/admin/vai-e-vem/' . $item['id'] . '/aprovar')) ?>"><input type="hidden" name="_csrf" value="<?= $e(App\Core\Security::csrfToken()) ?>"><button type="submit">Aprovar</button></form><?php endif; ?><?php if ($item['status'] === 'approved'): ?><form method="post" action="<?= $e(App\Core\Config::url('/admin/vai-e-vem/' . $item['id'] . '/publicar')) ?>"><input type="hidden" name="_csrf" value="<?= $e(App\Core\Security::csrfToken()) ?>"><button type="submit">Publicar</button></form><?php endif; ?><?php if ($item['status'] !== 'cancelled'): ?><form method="post" action="<?= $e(App\Core\Config::url('/admin/vai-e-vem/' . $item['id'] . '/cancelar')) ?>"><input type="hidden" name="_csrf" value="<?= $e(App\Core\Security::csrfToken()) ?>"><button type="submit">Cancelar</button></form><?php endif; ?></div>
<h2>Historico</h2><div class="table-wrap"><table><thead><tr><th>Data</th><th>Acao</th><th>Status</th><th>Usuario</th><th>Motivo</th></tr></thead><tbody><?php foreach ($history as $entry): ?><tr><td><?= $e($entry['created_at']) ?></td><td><?= $e($entry['action']) ?></td><td><?= $e(($entry['from_status'] ?: '-') . ' → ' . $entry['to_status']) ?></td><td><?= $e($entry['user_name']) ?></td><td><?= $e($entry['reason'] ?: '-') ?></td></tr><?php endforeach; ?></tbody></table></div>
